void compress_string(const char *src, char *dest) {
    if (!src || !dest)
        return;

    const char *p = src;
    int count = 0;
    char prev = '\0';
    int first = 1;

    while (*p) {
        if (first) {
            prev = *p;
            count = 1;
            first = 0;
        } else if (*p == prev) {
            count++;
        } else {
            *dest++ = prev;
            dest += sprintf(dest, "%d", count);
            prev = *p;
            count = 1;
        }
        p++;
    }

    if (count > 0) {
        *dest++ = prev;
        dest += sprintf(dest, "%d", count);
    }

    *dest = '\0';
}

